import sys, copy, docx
from docx.shared import Pt

src, out = sys.argv[1], sys.argv[2]
d = docx.Document(src)
body = d.element.body
paras = list(d.paragraphs)
title_p = paras[0]
# remove everything except the title paragraph (keep sectPr)
for p in paras[1:]:
    p._element.getparent().remove(p._element)

title_p.runs[0].text = "Η ιστορία του Ζόρνακ του Πανούργου"
for r in title_p.runs[1:]:
    r.text = ""

